    SELECT bg.GiaID, bg.RapID, r.TenRap, bg.LoaiGhe, bg.LoaiNgay, bg.DinhDang,
           bg.PhuThu, bg.NgayBatDau, bg.NgayKetThuc, bg.TrangThai
    FROM dbo.BANGGIA bg INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = bg.RapID
